// Fused Multiply-Add (FMA): Performance & Accuracy
// Standard allows reordering/FMA unless strictly disabled.
double a=3.0, b=4.0, c=5.0;

// Standard calculation: two roundings (A*B then +C)
double r_std = a * b + c;

// FMA instruction (hardware optimized, one rounding)
// Faster and often higher precision (r_fma != r_std possible)
double r_fma = fma(a, b, c);

